using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;namespace AshkanJobCenter.UI{public class ActivityPage:UserControl{public ActivityPage(){BackColor=Theme.Background;var g=Ui.Grid();g.DataSource=Database.Query("SELECT TOP 500 a.Id,u.FullName AS [User],a.Action,a.Entity,a.Details,a.CreatedAt FROM AuditLog a LEFT JOIN Users u ON u.Id=a.UserId ORDER BY a.Id DESC");Controls.Add(g);}}}
